import numpy as np
T={'1':np.ones_like(t),'s':np.sqrt(t),'t':t,'1/s':1/np.sqrt(t),'lt':np.log(t),'1/t':1/t,'u':t/(1+t),'e-t':np.exp(-t),'t2':t*t}
Pb={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'PL':P*np.log(P),'L':np.log(P),'1/P':1/P,'P2L':P*P*np.log(P),'sqP':np.sqrt(P),'eP':np.exp(-P)}
cols=[];names=[]
for a in T:
    for b in Pb:
        cols.append(T[a]*Pb[b]);names.append(a+'*'+b)
F=np.column_stack(cols)
sel=[]
y=dP_dt
for step in range(10):
    best=None
    for j in range(F.shape[1]):
        if j in sel: continue
        A=F[:,sel+[j]]
        c=np.linalg.lstsq(A,y,rcond=None)[0]
        r=np.mean((A@c-y)**2)/np.var(y)
        if best is None or r<best[0]: best=(r,j)
    sel.append(best[1])
    A=F[:,sel];c=np.linalg.lstsq(A,y,rcond=None)[0]
    print(step,names[best[1]],'nmse',best[0])
print([ (names[j],round(v,4)) for j,v in zip(sel,c)])

